#requires -Version 5.1
[CmdletBinding()]
param([string]$ProjectPath = "")
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
# Resolve the project directory after parameter binding.
if ([string]::IsNullOrWhiteSpace($ProjectPath)) {
    $ProjectPath = $PSScriptRoot
}
if ([string]::IsNullOrWhiteSpace($ProjectPath)) {
    $ProjectPath = Split-Path -Parent $MyInvocation.MyCommand.Path
}
if ([string]::IsNullOrWhiteSpace($ProjectPath)) {
    throw 'Project path could not be determined. Pass -ProjectPath explicitly.'
}
function Get-ContentHash([string]$File) {
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes(([IO.File]::ReadAllText($File)).Replace("`r`n","`n"))))).Replace('-','').ToLowerInvariant() }
    finally { $sha.Dispose() }
}
$items = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')) | ConvertFrom-Json
if (-not (Test-Path -LiteralPath $ProjectPath -PathType Container)) { throw 'Project directory not found.' }
$root = (Resolve-Path -LiteralPath $ProjectPath).Path
if (-not (Test-Path -LiteralPath (Join-Path $root 'package.json'))) {
    $nested = Join-Path $root 'tedarikya-react'
    if (Test-Path -LiteralPath (Join-Path $nested 'package.json')) { $root = $nested }
    else { throw 'Run this script in the React project or pass -ProjectPath.' }
}
$package = Get-Content -LiteralPath (Join-Path $root 'package.json') -Raw | ConvertFrom-Json
if ($package.name -ne 'tedarikya-txt-studio') { throw 'This is not the expected Tedarikya React project.' }
if (-not (Get-Command npm.cmd -ErrorAction SilentlyContinue)) { throw 'Install Node.js 22 LTS first (npm.cmd is required).' }
# Check every target before writing; protect unrecognized local changes.
foreach ($item in $items) {
    $target = Join-Path $root $item.path
    if (Test-Path -LiteralPath $target) {
        $actual = Get-ContentHash $target
        if ($actual -ne $item.oldHash -and $actual -ne $item.newHash) {
            throw "Local changes detected in $($item.path). No files changed. Keep a copy and use the full updated ZIP separately."
        }
    } elseif ($item.oldHash) { throw "Required file missing: $($item.path). No files changed." }
}
$backup = Join-Path $root ('tedarikya-backup-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [Guid]::NewGuid().ToString('N').Substring(0,6))
New-Item -ItemType Directory -Path $backup | Out-Null
$records = @()
foreach ($item in $items) {
    $target = Join-Path $root $item.path
    $existed = Test-Path -LiteralPath $target
    $saved = Join-Path $backup $item.path
    if ($existed) {
        New-Item -ItemType Directory -Force -Path (Split-Path $saved -Parent) | Out-Null
        Copy-Item -LiteralPath $target -Destination $saved
    }
    $records += [PSCustomObject]@{target=$target;saved=$saved;existed=$existed}
}
try {
    foreach ($item in $items) {
        $target = Join-Path $root $item.path
        $temp = $target + '.' + [Guid]::NewGuid().ToString('N') + '.tmp'
        try {
            [IO.File]::WriteAllBytes($temp,[Convert]::FromBase64String($item.base64))
            if ((Get-ContentHash $temp) -ne $item.newHash) { throw 'Payload checksum mismatch.' }
            Move-Item -LiteralPath $temp -Destination $target -Force
        } finally { if (Test-Path -LiteralPath $temp) { Remove-Item -LiteralPath $temp -Force } }
    }
    Push-Location -LiteralPath $root
    try {
        if (-not (Test-Path -LiteralPath (Join-Path $root 'node_modules/vite/package.json'))) {
            & npm.cmd ci
            if ($LASTEXITCODE -ne 0) { throw 'npm ci failed.' }
        }
        & npm.cmd run build
        if ($LASTEXITCODE -ne 0) { throw 'Build failed.' }
    } finally { Pop-Location }
    Write-Host "Update completed. Build passed. Backup: $backup" -ForegroundColor Green
    Write-Host 'Upload the changed source files to GitHub to redeploy on Vercel.'
} catch {
    $failure = $_
    foreach ($record in $records) {
        if ($record.existed) { Copy-Item -LiteralPath $record.saved -Destination $record.target -Force }
        elseif (Test-Path -LiteralPath $record.target) { Remove-Item -LiteralPath $record.target -Force }
    }
    Write-Warning "Source files restored. Backup: $backup"
    throw $failure
}
